package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.util.List;import java.nio.file.*;
public class RootStableReadinessContractTest {
 @Test public void v28OneFrameDiagnosticRetainsOldNamespaces(){assertNotEquals(RootFamilyDiagnosticProfile.DIRECTORY,RootFamilyDiagnosticProfile.V25_DIRECTORY);assertNotEquals(RootFamilyDiagnosticProfile.DIRECTORY,RootCaptureScope.PREFLIGHT_DIRECTORY);assertTrue(RootFamilyDiagnosticProfile.ACTIVE);assertFalse(RootFamilyDiagnosticProfile.modeAllowed(RootCaptureScope.Mode.BUSINESS));assertNotEquals(RootFamilyDiagnosticProfile.DIRECTORY,RootFamilyDiagnosticProfile.V26_DIRECTORY);assertFalse(RootFamilyDiagnosticProfile.phaseAllowed(RootCaptureScope.Mode.PREFLIGHT,RootCaptureScope.Phase.SECOND));}
 @Test public void newOwnAndErrorLiteralsAreDiagnosticOnly(){var d=MaaRecognizer.rootMarkers(List.of(new FrameStructureEvidence.Line("Root 任务卡只读诊断 v26",0,0,20,10,.99),new FrameStructureEvidence.Line("只读任务卡诊断：1帧，零输入",0,20,20,10,.99),new FrameStructureEvidence.Line("出现问题",0,40,20,10,.99),new FrameStructureEvidence.Line("Root 任务卡原生验证 v27",0,60,20,10,.99)));assertEquals(4,d.markers().stream().mapToInt(MaaRecognizer.RootMarkerCount::highConfidence).sum());assertTrue(d.summary().contains("DIAGNOSTIC_ONLY"));assertTrue(d.summary().contains("targetIdentity=UNPROVEN"));assertFalse(d.summary().contains("出现问题"));}
 @Test public void normalRefreshIsNotAnErrorMarker(){var d=MaaRecognizer.rootMarkers(List.of(new FrameStructureEvidence.Line("刷新",0,0,20,10,.99)));assertEquals(0,d.markers().stream().mapToInt(MaaRecognizer.RootMarkerCount::candidates).sum());}
 private static String source(String n)throws Exception{Path p=Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",n);if(!Files.exists(p))p=Path.of("app/src/main/java/com/aliothmoon/maafw/once",n);return Files.readString(p);}
 @Test public void onlyExplicitTransitionCanBeObservedAgain()throws Exception{String s=source("CaptureSessionRuntime.java");assertTrue(s.contains("int limit=3;"));assertTrue(s.contains("result.status()!=BingNavigationSnapshot.Status.BING_TRANSITION)break"));assertTrue(s.contains("forRootPhaseSource(activity.getApplicationContext(),installed,bingUid,systemUid,rootSourceReadPermit)"));assertTrue(s.contains("after.status()==BingNavigationSnapshot.Status.READY&&rootPreflightBefore.sameSource(after.ready())"));}
}
